const search=ico('<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>'),pin=ico('<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0z"/><circle cx="12" cy="10" r="2.5"/>'),arrow=ico('<path d="M5 12h14m-6-6 6 6-6 6"/>'),bag=ico('<path d="M5 8h14l1 13H4zM9 9V6a3 3 0 0 1 6 0v3"/>');
