const cards=shops.map(s=>'<a class="local-card" href="/m/'+E(s.slug)+'"><div class="local-photo">'+(s.cover?'<img src="'+E(s.cover)+'" alt="" loading="lazy" onerror="this.onerror=null;this.src=\'/brand/store.svg\'">':s.product_image?'<img class="local-product-photo" src="'+E(s.product_image)+'" alt="'+E(s.product||'')+'" loading="lazy" onerror="this.onerror=null;this.src=\'/brand/store.svg\'">':'<img class="local-placeholder" src="/brand/store.svg" alt="">')+'</div><div class="local-info"><div class="local-title">'+(s.logo?'<img src="'+E(s.logo)+'" alt="" onerror="this.hidden=true">':'<span class="local-initial">'+E(s.name.slice(0,1).toUpperCase())+'</span>')+'<div><h3>'+E(s.name)+'</h3><small>'+E(s.city)+'</small></div>'+arrow+'</div>'+(s.product?'<div class="local-product"><span>'+E(s.product)+'</span><b>'+cash(s.price)+'</b></div>':'')+'<div class="local-modes">'+(s.pickup?'<span>Recogida</span>':'')+(s.delivery||s.network_delivery?'<span>Envío</span>':'')+'</div></div></a>').join('');
