app.post('/estado',guard,async(q,r)=>{const b=q.body,o=await one('SELECT status,mode,delivery_kind FROM orders WHERE id=$1 AND shop=$2',S(b.id,64),q.shop.id);if(!o||!states[o.status].includes(b.status)||(b.status==='En camino'&&o.mode!=='delivery')||(o.delivery_kind==='network'&&(['En camino','Entregado'].includes(b.status)||o.status==='En camino')))return err(r,'Cambio no permitido');const result=await sql('UPDATE orders SET status=$1 WHERE id=$2 AND shop=$3 AND status=$4',b.status,b.id,q.shop.id,o.status);if(!result.rowCount)return err(r,'El pedido cambió de estado',409);realtime.publish(q.shop.id);if(q.get('accept')==='application/json')return r.json({ok:true,status:b.status});r.redirect('/panel')});

