 const top='<section class="store-head menu-brand-head" style="--store-accent:'+E(brand)+'"><div class="menu-cover-band '+(s.cover?'store-cover custom-cover':'')+'">'+(s.cover?'<img src="'+E(s.cover)+'" alt="" onerror="this.hidden=true">':'<img src="/brand/store.svg" alt="">')+'<a class="store-back" href="/explorar">← Explorar</a></div><div class="menu-head-content"><div class="store-identity">'+(s.logo?'<img class="store-logo" src="'+E(s.logo)+'" alt="" onerror="this.hidden=true">':'<div class="store-initial" aria-hidden="true">'+E(s.name.trim().slice(0,1).toUpperCase())+'</div>')+'<div class="store-info"><div class="row"><span class="store-status '+(status?'open':'closed')+'">'+(status?'Abierto':'Cerrado')+'</span></div><h1>'+E(s.name)+'</h1>'+(s.intro?'<p>'+E(s.intro)+'</p>':'')+'</div></div><div class="menu-store-facts">'+([s.address,s.neighborhood,s.city].filter(Boolean).length?'<span>'+icon('pin')+E([s.address,s.neighborhood,s.city].filter(Boolean).join(' · '))+'</span>':'')+(s.hours?'<span>'+icon('clock')+E(s.hours)+'</span>':'')+'</div><div class="store-modes">'+(s.pickup?'<span>'+icon('pickup')+'Recoger en tienda</span>':'')+(s.delivery?'<span>'+icon('delivery')+'Envío · '+cash(s.fee)+'</span>':'')+(drivers.length?'<span>'+icon('delivery')+'Reparto desde '+cash(drivers[0].fee)+'</span>':'')+'</div></div></section>';
 if(s.platform_blocked||!ps.length)return page(r,s.name,'<div class="store-page">'+top+'<div class="card empty"><h2>'+(s.platform_blocked?'No recibimos pedidos':'Menú no disponible')+'</h2></div></div>');
 const photo=p=>'<figure class="store-product-photo '+(p.image?'':'photo-placeholder')+'">'+(p.image?'<img src="'+E(p.image)+'" alt="'+E(p.name)+'" loading="lazy" onerror="this.onerror=null;this.src=\'/brand/store.svg\';this.closest(\'figure\').classList.add(\'photo-placeholder\')">':'<img src="/brand/store.svg" alt="">')+'</figure>';
