 const checkout='<aside class="card cart store-cart" id="cart"><div class="cart-heading"><div class="cart-icon">'+icon('bag')+'</div><h2>Tu pedido</h2><span class="pill" id="count">0 productos</span></div><div id="cartitems" class="cart-items"></div><div id="cart-checkout" hidden><div class="line row between"><span>Subtotal</span><b id="subtotal">$0.00</b></div><div class="line row between" id="feeRow"><span>Envío</span><b id="shipping-fee">'+cash(s.fee)+'</b></div><div class="row between store-total"><h2>Total</h2><h2 id="sum">$0.00</h2></div><div class="checkout-section"><label>¿Cómo quieres recibir tu pedido?<select name="mode" required onchange="total()"><option value="" disabled selected>Selecciona una modalidad</option>'+(s.pickup?'<option value="pickup">Recoger personalmente (sin repartidor)</option>':'')+(s.delivery?'<option value="delivery">Envío propio del negocio</option>':'')+(drivers.length?'<option value="network">Envío a domicilio con repartidor P-deme</option>':'<option disabled>Reparto P-deme · '+(s.network_delivery?'Sin repartidores disponibles':'No habilitado por este negocio')+'</option>')+'</select></label><p id="mode-notice" class="mode-notice" role="status">Selecciona recogida o envío a domicilio.</p><div id="driver-choice" hidden><label>Repartidor<select name="driver_quote" onchange="total()">'+drivers.map(d=>'<option value="'+d.id+':'+d.fee+'" data-fee="'+d.fee+'">'+E(d.name.split(' ')[0])+' · '+E(d.vehicle)+' · '+cash(d.fee)+'</option>').join('')+'</select></label></div>'+field('Nombre','customer',q.customer?.name||'','text',true)+field('Teléfono','phone',q.customer?.phone||'','tel',true)+'<div id="delivery">'+field('Dirección completa','address')+'<small>'+E(s.coverage)+' · Mínimo '+cash(s.minimum)+'</small></div><details><summary>Programar o añadir notas</summary>'+field('Hora (opcional)','scheduled','','datetime-local')+'<label>Indicaciones<textarea name="notes" maxlength="500"></textarea></label></details><p>Paga al recibir o recoger.</p><p style="font-size:11px">Tus datos se comparten con el comercio y, si corresponde, el repartidor asignado. <a href="/privacidad" target="_blank" rel="noopener">Privacidad</a>.</p><button id="submit" style="width:100%">Enviar pedido</button></div></div></aside>';
 const script='<script>let cat="";const f=document.querySelector(".store-page form"), money=n=>new Intl.NumberFormat("es-MX",{style:"currency",currency:"MXN"}).format(n/100);function setCat(b,c){cat=c;document.querySelectorAll(".filterbar button").forEach(x=>x.classList.toggle("selected",x===b));filterMenu()}function filterMenu(){let t=(document.querySelector("#search")?.value||"").toLowerCase().trim(),visible=0;document.querySelectorAll(".store-product").forEach(x=>{x.hidden=!!((cat&&x.dataset.category!==cat)||(t&&!x.dataset.name.includes(t)));if(!x.hidden)visible++});document.querySelectorAll(".menu-category").forEach(g=>g.hidden=![...g.querySelectorAll(".store-product")].some(x=>!x.hidden));document.querySelector("#menu-empty").hidden=visible!==0}function changeQty(b,d){let x=b.parentElement.querySelector("input");x.value=Math.max(0,Math.min(30,(Number(x.value)||0)+d));total()}function total(){let network=f.elements.mode.value==="network",d=network||f.elements.mode.value==="delivery",fee=network?Number(f.elements.driver_quote.selectedOptions[0]?.dataset.fee||0):'+s.fee+',n=0,c=0,box=document.querySelector("#cartitems");box.replaceChildren();for(let x of f.querySelectorAll("[data-price]")){let q=Math.max(0,Math.min(30,Math.trunc(Number(x.value)||0)));x.closest(".store-product")?.classList.toggle("in-cart",q>0);if(!q)continue;let p=q*Number(x.dataset.price);n+=p;c+=q;let line=document.createElement("div");line.className="row between line";let name=document.createElement("span");name.textContent=q+" × "+x.dataset.title;let amount=document.createElement("b");amount.textContent=money(p);line.append(name,amount);box.append(line)}if(!c){let p=document.createElement("p");p.className="store-empty-cart";const bag=document.createElement("span");bag.className="cart-empty-symbol";bag.setAttribute("aria-hidden","true");bag.innerHTML=\'<svg viewBox="0 0 48 48" width="52" height="52" fill="none" stroke="currentColor" stroke-width="2"><path d="M10 16h28l3 27H7zM18 18V12a6 6 0 0 1 12 0v6"/><path d="M19 29h10m-5-5v10" stroke-linecap="round"/></svg>\';p.append(bag,document.createTextNode("Añade productos del menú."));box.append(p)}document.querySelector("#cart-checkout").hidden=!c;document.querySelector("#delivery").hidden=!d;document.querySelector("#driver-choice").hidden=!network;document.querySelector("#mode-notice").textContent=network?"Se enviará una solicitud al repartidor seleccionado.":d?"El negocio realizará la entrega con su propio reparto.":f.elements.mode.value==="pickup"?"Tú recogerás el pedido. No se enviará a repartidores.":"Selecciona recogida o envío a domicilio.";document.querySelector("#submit").textContent=network?"Pedir con repartidor":d?"Pedir envío a domicilio":f.elements.mode.value==="pickup"?"Pedir para recoger":"Selecciona una modalidad";document.querySelector("#shipping-fee").textContent=money(fee);document.querySelector("#feeRow").hidden=!d;f.elements.address.required=d;document.querySelector("#count").textContent=c+" productos";document.querySelector("#subtotal").textContent=money(n);document.querySelector("#sum").textContent=money(n+(d&&c?fee:0));document.querySelector("#mobileSum").textContent=money(n+(d&&c?fee:0));document.querySelector("#mobileCount").textContent="Ver pedido ("+c+")";document.querySelector("#submit").disabled=!c||!f.elements.mode.value||(d&&n<'+s.minimum+')||(network&&!fee);document.querySelector("#mobile").hidden=!c}total()</script>';
 page(r,s.name,'<div class="store-page">'+top+form('/pedido/'+s.slug,'<div class="store-layout">'+items+checkout+'</div>')+'</div>'+'<button class="mobile-cart" id="mobile" onclick="document.querySelector(\'#cart\').scrollIntoView({behavior:\'smooth\'})"><span id="mobileCount">Ver pedido</span><span id="mobileSum"></span></button><style>[hidden]{display:none!important}</style>'+script);
